hadiths.text_ar:
حَدَّثَنَا  /26  الصلت بْن مَسْعُود الجحدري L1478  /26  ، حَدَّثَنَا  /26  حماد بْن زيد L2491  /26  ، حَدَّثَنَا  /26  عُبَيْد الله بْن يَحْيَى L8713  /26  ، عَن  /26  أَبِي جَعْفَر مُحَمَّد بْن علي L7187  /26  ، قَالَ : /27 " لما ظهر  /93  سعد L3232  /93  عَلَى حلوان العراق ، /20 بعث جعونة بْن نضلة فِي الطلب ، قَالَ : فأتينا عَلَى غار أو نقب فحضرت الصلاة ، فأذنت ، فقلتُ : الله أكبر الله أكبر . فأجابني مُجيب من الجبل ، كبرت كبيرًا ، فأجبتُ فرقًا . قلت : أشهد أن لا إله إلا الله . قَالَ : أخلصتَ . فالتفتُ يمينًا وشمالاً فلم أر أحدًا ، قلتُ : أشهد أن محمدًا رسول الله . قَالَ : نبي بعث . قلتُ : حي عَلَى الصلاة . قَالَ : فريضة وضعت . قلتُ : حي عَلَى الفلاح . قَالَ : قد أفلحَ من أجابَها واستجاب لَهَا . كل ذَلِكَ يَقُولُ ، فالتفت فلا أرى أحدًا    @ 1 : 179 @   ، قلت : جني أنت أم إنسي ؟ فأشرف علي شيخٌ أبيض الرأس واللحية ، قَالَ : أَنَا زريب بْن برثملا من حواري عيسى بْن مريم ، وأنا أشهدُ أن لا إله إلا الله ، وأن محمدًا رسول الله ، وإنه جاء بالحق من عِنْدَ الحق ، قد علمتُ مكانه فأردته ، فحالت بيني وبينه كفار فارس ، فأقرئ صاحبك السلام . فكتب سعد إلى عُمَر ، فكتب عُمَر : لا يفوتنك الرجل . فطلب فلم يوجد " /27 . موضوع ، قَالَ  /26  الخطيب  /26  : روى  /26  الراسبي  /26  ، عَن  /26  مالك  /26  هذا الحديث المنكر ، وابن  /26  لهيعة  /26  يدلس عَن ضعفاء ، وسليمان  /26  بْن أَحْمَد  /26  ضعيف . قَالَ  /26  ابن الْمَدِينِيّ : لَمْ  /26  يرو هذا إلا من  /26  وجه  /26  مجهول . قلتُ : أخرج  /26  البيهقي  /26  فِي الدلائل الحديث من الطريق  /26  الأول  /26  ، وقال : قَالَ  /26  أَبُو عَبْد الله الحافظ  /26  : كذا قَالَ  /26  عَبْد الرَّحْمَن بْن إِبْرَاهِيم الراسبي  /26  ، عَن  /26  مالك بْن أنس  /26  ،  /26  ولَمْ  /26  يتابع  /26  عَلَيْهِ  /26  ،  /26  ولَمْ  /26  يعرف هذا الحديث لِمالك  /26  بْن الأزهر  /26  ، عَن  /26  نافع ، وهو رجلٌ  /26  مجهول  /26  لَم  /26  نسمع بذكره فِي غير هذا الحديث ، ثُمَّ ساقه ، أَنْبَأنَا  /26  أَبُو عَبْد الله الحافظ  /26  ، حَدَّثَنَا  /26  أَبُو الْحُسَيْن إِسْمَاعِيل بْن مُحَمَّد بْن الفضل بْن مُحَمَّد الشعراني  /26  ، حَدَّثَنَا  /26  جدِّي  /26  ، حَدَّثَنَا  /26  مُحَمَّد بْن كرامة  /26  مستملي  /26  بْن الحماني  /26  بالكوفة ، حَدَّثَنَا  /26  سُلَيْمَان بْن أَحْمَد  /26  ، فذكره . ثُمّ قَالَ : هذا الحديث بِهذا الإسناد أشبه ،  /26  وهو  /26  ضعيف بالمرة . انتهى . وقال  /26  الذهبي  /26  فِي الميزان :  /26  عَبْد الرَّحْمَن بْن إِبْرَاهِيم الراسبي  /26  أتى عَن  /26  مالك  /26  بِهذا الخبر الباطل ،  /26  وهو  /26  المتهم بِهِ .  /26  وهو  /26  عِنْدَ  /26  إِبْرَاهِيم بْن عَبْد الله بْن أيوب  /26  المحزمي ، حَدَّثَنَا  /26  إِبْرَاهِيم بْن رجاء أَبُو مُوسَى  /26  ، عَن  /26  مالك  /26  ، بِهِ مختصرًا . انتهى . وقال  /26  الدَّارَقُطْنِيّ  /26  : لا يثبت عَن  /26  مالك  /26  ولا عَن  /26  نافع  /26  . وعرف  /26  من  /26  كلام  /26  الحاكم  /26  ،  /26  والبيهقي  /26  أن علة الطريق  /26  الثاني مالك بْن الأزهر  /26  لا  /26  سُلَيْمَان  /26  ، وأخرجه أَبُو نُعَيْم فِي الدلائل ،  /26  من طريق يَحْيَى بْن إِبْرَاهِيم بْن أَبِي  /26  قبيلة ، عَن  /26  زيد بْن أسلم  /26  ، عَن  /26  أَبِيهِ  /26  ، أن  /93  عُمَر L5913  /93  كتب إلى سعد ، بِهِ . وأخرجه الواقدي ، عَن  /26  عَبْد العزيز بْن عُمَر  /26  ، عَن جعونة  /26  بْن نضلة  /26  ، بِهِ . وأخرجه  /26  الباوردي  /26  فِي الصحابة ، من  /26  طريق أَبِي معروف عَبْد الله بْن معروف  /26  ، عَن  /26  أَبِي عَبْد الرَّحْمَن الْأنْصَارِيّ  /26  ، عَن  /26  مُحَمَّد بْن حسين بْن عَلِيّ بْن أَبِي طالب  /26  ، قَالَ : لَمّا ظهر  /26  سعد عَلَى حلوان  /26  . فذكره . وقال  /26  الخطيب  /26  : فِي رواة  /26  مالك  /26  ، أَنْبَأنَا  /26  أَبُو الْحَسَن أَحْمَد بْن عُمَر بْن روح النهرواني  /26  بِهَا ، والقاضي  /26  أَبُو عَبْد الله مُحَمَّد بْن عَبْد الله بْن أَحْمَد البيضاوي  /26  ببغداد ، وأبو  /26  الفرج   عَبْد الوهاب بْن الْحُسَيْن بْن عُمَر بْن برهان  /26 @ 1 : 180 @  /26  الغزال  /26  . بصور ، قَالُوا : أَنْبَأنَا  /26  الْحُسَيْن بْن مُحَمَّد بْن عُبَيْد الدقاق  /26  ، حَدَّثَنَا  /26  إِبْرَاهِيم بْن عَبْد الله بْن مُحَمَّد بْن أيوب المخرمي  /26  ، حَدَّثَنَا  /26  أَبِي  /26  ، حَدَّثَنَا  /26  إِبْرَاهِيم بْن رجاء أَبُو مُوسَى  /26  ، حَدَّثَنَا  /26  مالك بْن أنس  /26  ، عَن  /26  نافع  /26  ، عَن  /26  ابن عُمَر  /26  ، أن  /93  عُمَر L5913  /93  كتب إلى سعد : إذا أتاكَ كتابي هذا فادع نضلة . وذكر  /26  تَمام  /26  الحديث بطوله . وقال أيضًا حدَّثَنِي  /26  الأزهري  /26  ، حَدَّثَنَا  /26  ابن عُمَر الدَّارَقُطْنِيّ  /26  ، حدَّثَنِي  /26  عَبْد الرَّحْمَن بْن جَعْفَر الكرابيسي  /26  ، حَدَّثَنَا  /26  أَحْمَد بْن الْحَسَن بْن محمود بْن الخصر  /26   /26  الطالقاني  /26  ، حَدَّثَنَا  /26  عمارة بْن وثيمة  /26  ، قَالَ : وجدتُ فِي كتاب  /26  الْعَبَّاس بْن عَبْد الله بْن اليسع  /26  ، عَن  /26  إِبْرَاهِيم الحجري  /26  ، أخبرني  /26  مالك بْن أنس  /26  ، عَن  /26  نافع  /26  ، عَن  /26  ابن عُمَر  /26  L4967 ، قَالَ : كتب  /93  عُمَر L5913  /93  إلى سعد وهو بالقادسية : أمّا بعد ، فجهز نضلة بْن مُعَاويَة الْأنْصَارِيّ إلى حلوان العراق . وذكر الحديث بطوله . قَالَ فِي الميزان :  /26  إِبْرَاهِيم بْن رجاء  /26  ، عَن  /26  مالك  /26  لا يُعرف ، والخبر كذب ، وإبراهيم  /26  بْن عَبْد الله  /26  المجزمي ، قَالَ فِيهِ  /26  الإسماعيلي  /26  : صدوق . لكن قَالَ  /26  الدَّارَقُطْنِيّ : لَيْسَ  /26  بثقة ، حَدَّث عَن ثقات بأحاديث باطلة  * 
